function upgrade(d){d.equipmentTypes??=initialEquipmentTypes();d.owners??=[];d.ownerContacts??=[];d.mailTemplates??=defaultMailTemplates();d.verifiers??=[];for(const e of d.equipment)for(const c of e.controls){if(c.intervenant&&!d.verifiers.some(name=>normalize(name)===normalize(c.intervenant)))d.verifiers.push(c.intervenant);c.reportId??=`VGP-${c.date.replaceAll('-','')}-${c.id.toUpperCase()}`;}let next=Math.max(0,...d.equipment.map(e=>Number.isSafeInteger(e.siteId)?e.siteId:0))+1;for(const e of d.equipment)if(!e.siteId)e.siteId=next++;d.nextVgpId=Math.max(d.nextVgpId??1,next);for(const e of d.equipment){for(const k of ['serialNumber','sector','zone','team','owner','comments'])e[k]??='';e.archived??=false;e.archiveHistory??=[];e.pendingArchive??=null;for(const owner of equipmentOwners(e))if(!d.owners.some(o=>normalize(o)===normalize(owner)))d.owners.push(owner)}upgradeControllers(d,uuid);for(const e of d.equipment)for(const a of e.archiveHistory)if(a.workflow==='loss-declaration'&&!a.reportId)a.reportId=a.originalControlId?e.controls.find(c=>c.id===a.originalControlId)?.reportId||nextReportNumber(d):nextReportNumber(d);return d}
