async function synchronize(){
 if(syncing||cloud?.busy)return;
 if(document.querySelector('dialog[open]')||hasUnsavedForm()){syncError='Actualisation en attente : terminez ou fermez la saisie en cours.';refreshHomeStatus();return;}
 syncing=true;syncError='';refreshHomeStatus();const revision=cloud?.revision;
 try{
 if(cloud){const state=await cloud.read(false);if(!valid(state.payload))throw Error('Données reçues invalides : mise à jour bloquée.');if(cloud.busy||revision!==cloud.revision||document.querySelector('dialog[open]')||hasUnsavedForm())return;if(state.revision!==revision){data=upgrade(state.payload);cloud.revision=state.revision;pendingMigration=state.migration&&!state.migration.validated_at?{receipt:state.migration.id,document:state.payload}:null;render();}}
 else if(!memoryOnly&&!storageNeedsRecovery){const raw=localStorage.getItem(KEY);if(raw){const next=JSON.parse(raw);if(!valid(next))throw Error('Sauvegarde locale invalide : les données affichées sont conservées.');if(canonical(upgrade(next))!==canonical(data)){data=next;render();}}}
 lastUpdated=new Date();
 }catch(error){syncError=`Actualisation interrompue : ${error.message} Dernière réception à ${lastUpdated.toLocaleTimeString('fr-FR',{timeZone:'Europe/Paris'})}.`;}
 finally{syncing=false;refreshHomeStatus();}
}
