function checkDuplicates(){let ok=true;for(const field of ['identifier','serialNumber']){const input=$('#equipmentForm').elements[field];const value=normalize(input.value);const duplicate=value&&data.equipment.some(e=>e.id!==editing&&normalize(e[field])===value);const message=duplicate?(field==='identifier'?'Équipement déjà existant':'Numéro de série déjà existant'):'';input.setCustomValidity(message);input.setAttribute('aria-invalid',String(!!duplicate));$('#'+field+'Error').textContent=message;if(duplicate)ok=false}return ok}
function uppercaseInternalNumber(event){if(event.isComposing)return;const input=event.target,value=input.value,start=input.selectionStart,end=input.selectionEnd,direction=input.selectionDirection;if(value===value.toUpperCase())return;input.value=value.toUpperCase();if(start!==null)input.setSelectionRange(value.slice(0,start).toUpperCase().length,value.slice(0,end).toUpperCase().length,direction);}
$('#equipmentForm').elements.identifier.addEventListener('input',uppercaseInternalNumber);$('#equipmentForm').elements.identifier.addEventListener('compositionend',event=>{uppercaseInternalNumber(event);checkDuplicates();});
