async function save(next,replace=false){if(cloud?.role==='reader'){$('#message').textContent='Accès lecteur : aucune modification autorisée.';return false;}next=freezeTracking(upgrade(next),data,today(),accountName());if(storageNeedsRecovery&&!replace){$('#message').textContent='Enregistrement bloqué pour préserver les données existantes. Importez une sauvegarde valide.';return false}try{if(cloud){if(replace)throw Error('Le remplacement global est interdit en mode cloud. Utilisez la migration initiale dans Paramètres > Données.');await cloud.write(next);}else if(!memoryOnly){try{localStorage.setItem(KEY,JSON.stringify(next))}catch(error){if(error.name!=='SecurityError')throw error;memoryOnly=true;$('#storageNotice').hidden=false}}data=next;lastUpdated=new Date();syncError='';dirtyForms.delete(document.activeElement?.closest('form'));storageNeedsRecovery=false;$('#export').disabled=false;render();return true}catch(error){$('#message').textContent=cloud?error.message:'Enregistrement impossible : stockage plein ou indisponible. Les nouvelles données ne sont pas sauvegardées. Exportez une sauvegarde.';return false}}
