function equipmentLabel(e){return `<b class="equipment-name">${esc(equipmentName(e))}</b>${e.equipmentMark||e.location?`<span class="equipment-context">${esc([e.equipmentMark,e.location].filter(Boolean).join(' — '))}</span>`:''}${ownerNeedsNamingReview(e)?'<span class="owner-review-label">Propriétaire à vérifier</span>':''}<small>Numéro interne : ${esc(e.identifier)}</small><small>N° série : ${esc(e.serialNumber)||'Non renseigné'}</small><small>ID : ${e.siteId}</small>`}
function lastResult(e){if(materialArchived(e)&&lastArchive(e)?.workflow==='memoryflow-archive')return 'Mis au rebut — déclaration MemoryFlow';if(needsScrapControl(e))return 'Mis au rebut — contrôle à compléter';if(e.archived&&archiveReason(e)==='Mis au rebut'){const control=e.controls.find(c=>c.id===lastArchive(e)?.controlId);if(control)return control.result}const last=latest(e);if(e.memoryFlowTracking&&(!last||e.memoryFlowTracking.lastDate>last.date))return 'Date déclarée : '+fmt(e.memoryFlowTracking.lastDate)+' · résultat non renseigné';return last?.result||'Aucun contrôle'}
function lastResultDate(e){const archive=lastArchive(e);if(materialArchived(e)&&archive?.workflow==='memoryflow-archive'||needsScrapControl(e))return archive?.sourceDateUnknown?null:archive?.date||null;if(e.archived&&archiveReason(e)==='Mis au rebut'){const control=e.controls.find(c=>c.id===archive?.controlId);if(control)return control.date;}const last=latest(e);return e.memoryFlowTracking&&(!last||e.memoryFlowTracking.lastDate>last.date)?e.memoryFlowTracking.lastDate:last?.date||null;}
function materialVariant(e){return data.equipmentTypes.find(t=>t.id===e.typeId)?.variants.find(v=>v.id===e.variantId)?.name||'';}
function materialSortHeader(label,key){const active=$('#sortBy').value===key,descending=$('#sortOrder').value==='desc',nextDescending=active&&!descending,chronological=['lastResultDate','deadline'].includes(key),hint=chronological?(nextDescending?'du plus récent au plus ancien':'du plus ancien au plus récent'):(nextDescending?'décroissant':'croissant');return `<th scope="col" aria-sort="${active?(descending?'descending':'ascending'):'none'}"><button type="button" class="material-sort-header" data-material-sort="${key}" title="${label} : trier ${hint}" aria-label="${label} : trier ${hint}">${label}<span aria-hidden="true">${active?(descending?'▼':'▲'):'↕'}</span></button></th>`;}

function archiveReason(e){return e.archived?[...(e.archiveHistory??[])].reverse().find(a=>a.type==='archive')?.reason||'':''}
