function badge(e){if(lossArchived(e))return '<span class="badge lost-badge">Introuvable</span>';let s=status(e,today(),data.anticipation);if(s==='Archivé'){const reason=archiveReason(e);return `<span class="badge archive-badge ${reason==='Mis au rebut'?'scrapped-badge':reason==='Équipement perdu'?'lost-badge':''}">${esc(reason)||'Archivé'}</span>`}if(s==='Situation à vérifier')return `<button class="badge unknown date-link" data-deadline="${e.id}" aria-label="Définir la date du prochain contrôle de ${esc(e.identifier)}">Échéance à définir</button>`;return `<span class="badge ${s==='En retard'?'late':(s==='À venir'||s==='À faire')?'soon':s==='Situation à vérifier'?'unknown':'up-to-date'}">${deadlineLabel(s)}</span>`}
