const sort=$('#sortBy').value,direction=$('#sortOrder').value==='desc'?-1:1;const compare=(a,b)=>String(a??'').localeCompare(String(b??''),'fr',{numeric:true,sensitivity:'base'});
const sortValue=(e,key)=>key==='designation'?equipmentName(e):key==='variant'?materialVariant(e):key==='lastResultDate'?lastResultDate(e):key==='deadline'?(e.archived?null:due(e)):key==='owner'?equipmentOwners(e).join(', '):key==='state'?(lossArchived(e)?4:materialArchived(e)?5:({'En retard':0,'À faire':1,'Échéance à plus d’un mois':2,'Situation à vérifier':3}[status(e,today())]??3)):e[key];
