$('#mailTemplateForm').onsubmit=async ev=>{ev.preventDefault();const next=copyData(data),template=next.mailTemplates.find(t=>t.kind===$('#mailTemplateKind').value);const subject=$('#mailSubject').value.trim(),body=$('#mailBody').value.trim();const tokens=[...subject.matchAll(/\{\{([^{}]*)\}\}/g),...body.matchAll(/\{\{([^{}]*)\}\}/g)].map(m=>m[1].trim()),allowed=['nom_equipement','numero_interne','id_vgp','nom_proprietaire','date_controle','secteur','zone'];const unknown=tokens.filter(t=>!allowed.includes(t));if(unknown.length){$('#mailTemplateError').textContent='Champs inconnus : '+unknown.join(', ');return}template.subject=subject;template.body=body;if(!validTemplates(next.mailTemplates)){$('#mailTemplateError').textContent='Renseignez un objet et un message valides.';return}if(await save(next)){$('#mailTemplateError').textContent='';$('#mailTemplateSaved').textContent=`Modèle enregistré${memoryOnly?' pour cette session uniquement':''}.`;updateMailPreview()}else $('#mailTemplateError').textContent=$('#message').textContent};
