async function readControl(form,required){const f=new FormData(form),date=f.get('date'),file=f.get('attachment');if(!date){if(required||f.get('intervenant')||f.get('result')||f.get('observations')||file?.size)throw Error('Renseignez la date du contrôle ou laissez tous ses champs vides.');return null}if(f.get('result')==='Introuvable'&&!f.get('observations').trim())throw Error('Décrivez les recherches effectuées pour déclarer le matériel introuvable.');if(date>today())throw Error('Un contrôle réalisé ne peut pas être daté dans le futur.');if(f.get('intervenant').trim().length>160)throw Error('Le nom du vérificateur est limité à 160 caractères.');if(!f.get('result')||!f.get('intervenant').trim())throw Error('Renseignez le résultat et le contrôleur.');const verifier=activeControllers(data.controllerProfiles).find(p=>p.name===f.get('intervenant'));if(!verifier)throw Error('Choisissez un contrôleur enregistré dans sa fiche.');let attachment=null;if(file?.size){if(file.size>1024*1024)throw Error('Le justificatif dépasse 1 Mo.');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Utilisez un PDF ou une image PNG, JPEG ou WebP.');const url=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Lecture du fichier impossible.'));r.readAsDataURL(file)});attachment={name:file.name,type:file.type,url}}const id=uuid(),reportSignature=await signatureForPdf(verifier.signature),recordedAt=new Date();return {id,reportId:nextReportNumber(data),date,time:parisTime(recordedAt),timeZone:'Europe/Paris',recordedAt:recordedAt.toISOString(),reportSignature,verifierId:verifier.id,verifierSnapshot:{id:verifier.id,name:verifier.name,email:verifier.email},intervenant:verifier.name,result:f.get('result'),observations:f.get('observations'),attachment,created:recordedAt.getTime(),enteredBy:accountName(),enteredById:cloud?.session?.user?.id||null}}
