$('#controlForm').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button:not([type])');if(button.disabled)return;button.disabled=true;try{const c=await readControl(ev.target,true),next=copyData(data);c.enteredBy=accountName();c.enteredById=cloud?.session?.user?.id||null;const equipment=next.equipment.find(e=>e.id===selected);if(equipment.archived&&!(controlContext==='scrapCompletion'&&needsScrapControl(equipment)))throw Error('Désarchivez cet équipement avant d’enregistrer un contrôle.');if(controlContext==='scrapCompletion'&&c.result!=='Mauvais état — à jeter')throw Error('Le résultat d’une mise au rebut doit être « Mauvais état — à jeter ».');if(c.result==='Introuvable'){declareLoss(equipment,{id:c.id,date:c.date,author:c.intervenant,comment:c.observations,account:accountName(),attachment:c.attachment,reportId:c.reportId,equipmentSnapshot:equipmentSnapshot(equipment),verifierId:c.verifierId,reportSignature:c.reportSignature,time:c.time});}else{if(equipment.needsReverification&&c.date<equipment.lastFoundDate)throw Error('Le nouveau contrôle doit être réalisé après la réactivation.');if(!latestInspection(equipment)||c.date>=latestInspection(equipment).date)c.plannedDate=due(equipment);c.equipmentSnapshot=equipmentSnapshot(equipment);equipment.controls.push(c);equipment.needsReverification=false;}if(controlContext==='scrapCompletion')lastArchive(equipment).controlId=c.id;equipment.scheduledControl=null;if(await save(next)){$('#control').close();showDetail(selected);$('#message').textContent=`${c.result==='Introuvable'?'Introuvable — suivi suspendu. Aucun contrôle réalisé ajouté':'Contrôle enregistré'}${memoryOnly?' pour cette session uniquement':''}.`}else{$('#controlError').textContent=$('#message').textContent}}catch(e){$('#controlError').textContent=e.message}finally{button.disabled=false}};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-verifier')){const name=prompt('Nom du contrôleur à ajouter à l’onglet Contrôleurs :');if(name?.trim()){const value=name.trim();if(value.length>160)return;const next=copyData(data);let profile=controllerForName(next.controllerProfiles,value);if(profile?.deletedAt){alert('Cette fiche a été supprimée du répertoire. Choisissez un autre contrôleur.');return;}if(!profile){profile={id:uuid(),name:value,email:'',signature:null};next.controllerProfiles.push(profile);}if(await save(next)){const select=b.closest('label').querySelector('[data-controller-list]');select.value=profile.name;select.dispatchEvent(new Event('change',{bubbles:true}));}}}if(b.dataset.close){if(b.dataset.close==='editor')equipmentEditorGuard.close();else if(b.dataset.close==='detail')closeEquipmentPage();else $('#'+b.dataset.close).close();}if(b.dataset.open)showDetail(b.dataset.open);if(b.dataset.deadline){if($('#kpiListDialog').open)$('#kpiListDialog').close();openDeadline(b.dataset.deadline);}if(b.dataset.report)report(b.dataset.report);if(b.dataset.archiveReport)archiveDocument(b.dataset.archiveReport);if(b.dataset.deleteHistoryEntry)deleteHistoryEntry(b.dataset.deleteHistoryEntry,b);if(b.dataset.controlPdf)downloadControlPdf(b.dataset.controlPdf)});
