function controlHistoryTableHtml(e){const rows=equipmentControlHistory(e);return `<h3>Historique des contrôles et déclarations</h3>${rows.length?`<div class="control-history-scroll"><table class="control-history-table"><thead><tr><th scope="col">Date</th><th scope="col">Statut</th><th scope="col">Contrôleur</th><th scope="col">N° du contrôle</th><th scope="col">Rapport</th></tr></thead><tbody>${rows.map(c=>{const tone=c.result==='Introuvable'?'lost':c.result==='Bon état'?'good':c.result==='Mauvais état — à jeter'?'discard':'warning';return `<tr><td>${fmt(c.date)}</td><td><span class="control-result control-result-${tone}">${esc(c.result)}</span></td><td>${esc(c.intervenant)||'Non renseigné'}</td><td>${esc(c.reportId)||'Non renseigné'}</td><td><div class="actions"><button type="button" class="secondary" data-report="${esc(c.id)}">Lire le rapport</button><button type="button" class="secondary" data-control-pdf="${esc(c.id)}">Télécharger le PDF</button></div><details><summary>Détails</summary>${c.kind==='loss'?'<p>Déclaration introuvable · suivi suspendu.</p>':''}<p>${esc(c.observations)||'Aucune observation'}</p><small>Compte de saisie : ${esc(c.enteredBy)||'Non renseigné'}</small>${c.attachment?`<p><a href="${esc(c.attachment.url)}" download="${esc(c.attachment.name)}">Justificatif : ${esc(c.attachment.name)}</a></p>`:''}${c.apave?apaveSourceHtml(c.apave)+`<p><b>Résultat source APAVE</b><br>${esc((e.apaveChecks||[]).find(a=>a.controlId===c.id)?.resultText||'')}</p>`:''}${c.kind==='loss'?`<p><button type="button" class="danger" data-delete-history-entry="${esc(c.id)}">Supprimer cette entrée</button></p>`:''}</details></td></tr>`;}).join('')}</tbody></table></div>`:'<p>Aucun contrôle ni déclaration enregistré.</p>'}`;}
