function attachmentValid(a){return a&&typeof a.name==='string'&&typeof a.url==='string'&&/^data:(application\/pdf|image\/(png|jpeg|webp));base64,[A-Za-z0-9+/=]+$/.test(a.url)}
function archiveDataValid(d){if(!Array.isArray(d?.equipment))return false;const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s));const request=a=>a&&typeof a.id==='string'&&['archive','restore'].includes(a.type)&&typeof a.reason==='string'&&a.reason.trim()&&(a.type!=='archive'||['Équipement perdu','Mis au rebut'].includes(a.reason))&&date(a.date)&&typeof a.requester==='string'&&a.requester.trim()&&typeof a.observations==='string'&&typeof a.created==='number'&&typeof a.generated==='boolean'&&a.snapshot&&['identifier','serialNumber','designation','category','location','sector','team','owner','assignment'].every(k=>typeof a.snapshot[k]==='string');return d.equipment.every(e=>{if(e.archived!==undefined&&typeof e.archived!=='boolean')return false;if(e.pendingArchive!=null&&(!request(e.pendingArchive)||e.pendingArchive.type!==(e.archived?'restore':'archive')))return false;if(e.archiveHistory!==undefined&&(!Array.isArray(e.archiveHistory)||!e.archiveHistory.every(a=>((['loss-declaration','restore-found'].includes(a?.workflow)&&a.id&&date(a.date)&&a.requester?.trim()&&a.observations?.trim()&&((a.workflow==='loss-declaration'&&a.type==='archive'&&a.reason==='Équipement perdu')||(a.workflow==='restore-found'&&a.type==='restore'))&&(!a.attachment||attachmentValid(a.attachment)))||(a.workflow==='apave-disposal'&&a.id&&a.type==='archive'&&a.reason==='Mis au rebut'&&date(a.date)&&a.requester?.trim()&&typeof a.observations==='string'&&a.operatorConfirmed===true&&e.controls?.some(c=>c.id===a.controlId&&c.result==='Mauvais état — à jeter'&&c.apave?.reportHash===a.apave?.reportHash&&c.apave?.sourceKey===a.apave?.sourceKey))||(a.workflow==='memoryflow-archive'&&a.id&&a.type==='archive'&&['Équipement perdu','Mis au rebut'].includes(a.reason)&&date(a.date)&&a.requester?.trim()&&a.observations?.trim()&&a.sourceArchiveConfirmed===true&&a.sourceDateUnknown===true&&Array.isArray(a.sourceIds))||(request(a)&&a.generated&&date(a.approvalDate)&&a.approvalDate>=a.date&&typeof a.approver==='string'&&a.approver.trim()&&typeof a.validated==='number'&&attachmentValid(a.signedAttachment)&&(a.type!=='restore'||e.controls?.some(c=>c.id===a.controlId)))))))return false;return !e.archived||e.archiveHistory?.at(-1)?.type==='archive'})}

function loadDateValidation(e){const f=$('#equipmentForm');f.elements.manualDateConfirmed.checked=!!e?.dateValidation?.validated;f.elements.manualDateSource.value=e?.dateValidation?.source||'Saisie manuelle';f.elements.manualDateReason.value=e?.dateValidation?.reason||'Échéance saisie manuellement';f.elements.manualDateAuthor.value=e?.dateValidation?.by||accountName();}
function applyDateValidation(e,old,f){
 const previous=old?.periodicityValidation,samePeriod=old?.months===e.months;
 if(previous?.validated&&samePeriod)e.periodicityValidation=previous;
 else {const type=data.equipmentTypes.find(t=>t.id===f.get('typeId')),by=accountName(),reason=type?'Périodicité de suivi sélectionnée pour cette fiche de type « '+type.name+' ».':'Périodicité de suivi sélectionnée pour cette fiche en nom libre.';e.periodicityValidation={validated:true,months:e.months,reason,by,account:by,at:new Date().toISOString()};e.dateHistory=[...(old?.dateHistory||[]),{kind:'periodicity',date:today(),at:new Date().toISOString(),by,account:by,previousMonths:old?.months??null,months:e.months,maintainedDeadline:old?due(old):null,effectiveAfterNextControl:!!old&&old.months!==e.months&&!!due(old),reason,validated:true}];}

 const manual=e.manualNextControlDate,source=f.get('manualDateSource').trim(),justification=f.get('manualDateReason').trim(),author=f.get('manualDateAuthor').trim(),accepted=f.get('manualDateConfirmed')==='on';
 if(manual&&(manual!==old?.manualNextControlDate||accepted)&&(!accepted||!source||!justification||!author))throw Error('Confirmez la date manuelle et renseignez son auteur.');
 if(manual&&accepted){const oldV=old?.dateValidation;const same=manual===old?.manualNextControlDate&&oldV?.validated&&oldV.source===source&&oldV.reason===justification&&oldV.by===author;e.dateValidation=same?oldV:{validated:true,source,reason:justification,by:author,account:accountName(),at:new Date().toISOString()};if(!same)e.dateHistory=[...(e.dateHistory||old?.dateHistory||[]),{kind:'deadline',date:today(),at:new Date().toISOString(),previousDate:old?.manualNextControlDate??null,dateValue:manual,source,reason:justification,by:author,account:accountName()}];}
 else if(manual)e.dateValidation=old?.dateValidation||{validated:false};
 else if(old?.manualNextControlDate){e.dateValidation={validated:false};e.dateHistory=[...(e.dateHistory||old?.dateHistory||[]),{kind:'deadline',date:today(),at:new Date().toISOString(),previousDate:old.manualNextControlDate,dateValue:null,source:'Saisie de la fiche',reason:'Retrait de la date manuelle — retour à la règle validée si exploitable',by:accountName(),account:accountName()}];}
}
function dateAuditHtml(e){return `<details class="archive-info"><summary>Historique des dates et périodicités (${e.dateHistory?.length||0})</summary>${e.needsReverification?'<p class="error">Matériel retrouvé : nouveau contrôle obligatoire.</p>':''}${(e.dateHistory||[]).map(h=>`<p>${fmt(h.date)} · ${esc(h.kind==='deadline'?'Échéance':'Périodicité')} · ${esc(h.by)}${h.dateValue?' · '+fmt(h.dateValue):''}${h.months?' · '+h.months+' mois':''}${h.reason?'<br>'+esc(h.reason):''}</p>`).join('')||'<p>Aucune modification enregistrée.</p>'}</details>`;}

function importAuditHtml(e){const source=e.sourceImport;if(source?.format!=='MemoryFlow')return '';return `<section class="archive-info"><h3>Informations conservées de l’import Excel</h3><p>ID source : ${esc(source.externalId)} · ${source.sourceLines?.length||0} lignes conservées.<br>${esc(source.fileName||'')} · Compte de saisie : ${esc(source.importedBy||'Non renseigné')}</p><p>Ces données ne constituent pas des contrôles réalisés validés. Les dates, niveaux, grilles et observations d’origine restent consultables ci-dessous.</p><details><summary>Afficher les lignes source conservées</summary>${(source.sourceLines||[]).map(r=>`<details><summary>Ligne ${r.line} · ${esc(r.fields.Type||'Suivi source')}</summary><dl>${Object.entries(r.fields).map(([k,v])=>`<dt><b>${esc(k)}</b></dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`).join('')}</details></section>`;}
function historyDisplayRemovalsHtml(e){const removed=e.historyDisplayRemovals||[];return removed.length?`<details class="archive-info"><summary>Entrées supprimées de l’affichage (${removed.length})</summary><p class="foot">Trace conservée. Ces suppressions ne changent pas le statut ou les échéances de l’équipement.</p>${removed.map(r=>{const a=e.archiveHistory.find(a=>a.id===r.eventId);return a?`<p><b>${a.workflow==='loss-declaration'?'Déclaration introuvable':'Matériel retrouvé'}</b> · ${fmt(a.date)}<br>Retirée le ${fmt(r.date)} par ${esc(r.by)}${a.workflow==='loss-declaration'?`<br><button class="secondary" data-control-pdf="${esc(a.id)}">Télécharger le PDF conservé</button>`:''}</p>`:''}).join('')}</details>`:'';}
async function deleteHistoryEntry(id,button){
 const equipmentId=selected,e=data.equipment.find(e=>e.id===equipmentId),a=e?.archiveHistory.find(a=>a.id===id);if(!a||button.disabled||!['loss-declaration','restore-found'].includes(a.workflow))return;
 if(!confirm(`Supprimer cette entrée du ${fmt(a.date)} de l’affichage ?\n\nLe statut actuel, les échéances et les contrôles de l’équipement resteront inchangés. Une trace et le rapport éventuel seront conservés dans « Entrées supprimées de l’affichage ».\n\nConfirmer la suppression ?`))return;
 button.disabled=true;try{const next=copyData(data),equipment=next.equipment.find(e=>e.id===equipmentId);equipment.historyDisplayRemovals??=[];if(equipment.historyDisplayRemovals.some(r=>r.eventId===id))return;equipment.historyDisplayRemovals.push({eventId:id,date:today(),at:new Date().toISOString(),by:accountName()});if(await save(next)){showDetail(equipmentId);$('#message').textContent='Entrée supprimée de l’affichage. Trace conservée.';}}finally{button.disabled=false;}
}
function eventHistoryHtml(a){return `<article class="history"><b>${a.workflow==='loss-declaration'?'Introuvable — suivi suspendu':'Matériel retrouvé — situation à vérifier'} · ${fmt(a.date)}</b><p>Auteur déclaré : ${esc(a.requester)}<br>Compte de saisie : ${esc(a.account||'Compte historique non renseigné')}<br>${esc(a.observations)}</p>${a.originalControlId?`<p class="foot">Enregistrement historique conservé : ${esc(a.originalControlId)}. Exclu des vérifications effectuées.</p>`:''}${a.workflow==='loss-declaration'?`<small class="report-reference">Rapport ${esc(a.reportId)}</small><div class="actions"><button class="secondary" data-control-pdf="${esc(a.id)}">Télécharger le PDF</button><button class="secondary" data-report="${esc(a.id)}">Compte rendu / PDF</button></div>`:''}${a.attachment?`<a href="${esc(a.attachment.url)}" download="${esc(a.attachment.name)}">Justificatif : ${esc(a.attachment.name)}</a>`:''}<div class="actions"><button type="button" class="danger" data-delete-history-entry="${esc(a.id)}">Supprimer cette entrée</button></div></article>`;}
function openFound(e){$('#foundForm').reset();$('#foundForm').elements.date.value=today();$('#foundForm').elements.date.max=today();$('#foundForm').elements.author.value=accountName();$('#foundError').textContent='';$('#foundDialog').showModal();}
$('#foundForm').onsubmit=async event=>{event.preventDefault();try{const f=new FormData(event.target),next=copyData(data),e=next.equipment.find(e=>e.id===selected);if(!e?.archived)throw Error('L’équipement n’est plus archivé.');if(f.get('date')>today())throw Error('Date future impossible.');reactivateFound(e,{id:uuid(),date:f.get('date'),author:f.get('author'),comment:f.get('comment'),account:accountName()});if(await save(next)){$('#foundDialog').close();materialScope='active';showDetail(selected)}else $('#foundError').textContent=$('#message').textContent;}catch(error){$('#foundError').textContent=error.message}};
function trackingReviewText(){const r=migrationReview(data);return `${r.lossControls} ancien(s) enregistrement(s) Introuvable à conserver comme trace, dont ${r.activeLost} équipement(s) encore actifs à archiver. ${r.datesToValidate} situation(s) à vérifier ; ${r.unlinked} contrôle(s) réel(s) sans échéance d’origine connue. Aucun commentaire ni document ne sera supprimé.`;}
$('#migrateTracking').onclick=async()=>{try{if(!confirm(trackingReviewText()+' Exportez d’abord une sauvegarde. Confirmer cette migration additive ?'))return;const next=migrateTracking(data,today(),accountName());if(!valid(next))throw Error('Migration bloquée : format invalide. La source est conservée.');if(await save(next)){$('#trackingReview').textContent=trackingReviewText();$('#dataStatus').textContent='Migration métier enregistrée. Tous les contrôles, commentaires et documents d’origine restent présents.';}else $('#dataStatus').textContent=$('#message').textContent;}catch(error){$('#dataStatus').textContent=error.message}};


function selectNamingTab(name,focus=true){const names=['Proposals','Catalogue','Matches'];for(const n of names){const tab=$('#naming'+n+'Tab'),active=n===name;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$('#naming'+n+'Panel').hidden=!active;}if(focus)$('#naming'+name+'Tab').focus();}
for(const name of ['Proposals','Catalogue','Matches']){const tab=$('#naming'+name+'Tab');tab.onclick=()=>selectNamingTab(name);tab.onkeydown=event=>{const names=['Proposals','Catalogue','Matches'],index=names.indexOf(name);if(['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();selectNamingTab(names[event.key==='Home'?0:event.key==='End'?2:(index+(event.key==='ArrowRight'?1:2))%3]);}};}
function renderActiveFilters(){const labels=[['search','Recherche'],['filter','Statut'],['sectorFilter','Secteur'],['zoneFilter','Zone'],['teamFilter','Équipe'],['typeFilter','Type'],['variantFilter','Variante'],['archiveReasonFilter','Motif d’archivage']];$('#activeFilters').textContent='Périmètre : '+({all:'Tous les équipements',active:'En suivi · matériel actif',archived:'Archives · introuvables et mis au rebut'}[materialScope])+' · '+(labels.filter(([id])=>$('#'+id).value&&(id!=='archiveReasonFilter'||materialScope!=='active')).map(([id,label])=>label+' : '+($('#'+id).tagName==='SELECT'?$('#'+id).selectedOptions[0]?.textContent:$('#'+id).value)).concat(ownerFilter!==null?['Propriétaire : '+(ownerFilter||'Sans propriétaire')]:[]).join(' · ')||'Aucun filtre actif');}
