function routeEquipment(){if(equipmentEditorGuard.dirty()){const target=location.href;history.replaceState(null,'',location.pathname+location.search+(currentView==='equipment'?'#equipment/'+encodeURIComponent(selected):'#'+currentView));equipmentEditorGuard.request(()=>{$('#editor').close();history.replaceState(null,'',target);routeEquipment();});return;}if(location.hash.startsWith('#equipment/')){try{showDetail(decodeURIComponent(location.hash.slice(11)))}catch{setView('material')}}else if(currentView==='equipment')setView(['home','material','owners','controllers','kpi','actionKpi','mailSettings','reportSettings','shiftCalendar','planning','imports','administration','naming'].includes(location.hash.slice(1))?location.hash.slice(1):'material',null,true);}


let autoNamingName='',catalogContext=null,namingSelection=new Set(),namingPreview=null;
function namingOptions(select,selected=''){select.innerHTML='<option value="">Choisir un type d’équipement</option>'+(select.id==='equipmentType'?'<option value="__free__">Nom libre / non standardisé</option>':'')+[...data.equipmentTypes].sort((a,b)=>a.name.localeCompare(b.name,'fr',{sensitivity:'base',numeric:true})).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');select.value=selected;}
