function loadNamingFields(typeId='',variantId=''){autoNamingName='';delete $('#equipmentForm').elements.months.dataset.type;namingOptions($('#equipmentType'),typeId);variantOptions($('#equipmentVariant'),typeId==='__free__'?'':typeId,variantId);updateNamingPreview(false);}
function updateNamingPreview(fillName=true){updateCatalogRenameButtons();const f=$('#equipmentForm'),choice=f.elements.typeId.value,type=choice==='__free__'?'':choice,variant=f.elements.variantId.value,label=standardizedLabel(data.equipmentTypes,type,variant);$('#standardNamePreview').textContent=label?'Nom de l’équipement : '+label+'.':choice==='__free__'?'Nom libre : vous pouvez saisir le nom.':'Choisissez un type ou « Nom libre » pour renseigner le nom.';$('#addEquipmentVariant').disabled=!type;f.elements.designation.readOnly=choice!=='__free__';if(!fillName&&label)f.elements.designation.value=label;if(fillName){if(label)f.elements.designation.value=label;else if(choice!=='__free__')f.elements.designation.value='';else if(autoNamingName)f.elements.designation.value=editing?data.equipment.find(e=>e.id===editing)?.designation||'':'';autoNamingName=label;}const t=data.equipmentTypes.find(t=>t.id===type),period=f.elements.months;if(period.dataset.type!==(type||'free')){if(!editing)period.value=t?.months?String(t.months):type?'':'12';period.dataset.type=type||'free';}period.disabled=false;$('#equipmentPeriodHelp').textContent=editing?'Modifiable pour cette fiche. Un changement de nom ou de variante conserve votre choix. L’échéance du cycle en cours reste conservée.':t?.months?`Valeur proposée pour ce type : ${t.months} mois. Modifiable pour cette fiche.`:'Choisissez la périodicité de suivi de cette fiche.';}

$('#equipmentType').onchange=()=>{variantOptions($('#equipmentVariant'),$('#equipmentType').value==='__free__'?'':$('#equipmentType').value);updateNamingPreview();};$('#equipmentVariant').onchange=()=>updateNamingPreview();$('#equipmentForm').elements.designation.addEventListener('input',()=>{autoNamingName='';});
function updateCatalogRenameButtons(){for(const context of ['equipment','bulk']){const type=$('#'+(context==='equipment'?'equipmentType':'bulkNamingType')).value,variant=$('#'+(context==='equipment'?'equipmentVariant':'bulkNamingVariant')).value;$('#'+(context==='equipment'?'renameEquipmentType':'bulkRenameType')).disabled=!type||type==='__free__';$('#'+(context==='equipment'?'renameEquipmentVariant':'bulkRenameVariant')).disabled=!type||type==='__free__'||!variant;}}

function openCatalogItem(kind,context,rename=false){const typeId=context==='equipment'?$('#equipmentType').value:$('#bulkNamingType').value,variantId=context==='equipment'?$('#equipmentVariant').value:$('#bulkNamingVariant').value,type=data.equipmentTypes.find(t=>t.id===typeId),item=kind==='variant'?type?.variants.find(v=>v.id===variantId):type;if(kind==='variant'&&!type||rename&&!item)return;catalogContext={kind,context,typeId,variantId,rename};$('#catalogItemForm').reset();$('#catalogItemHelp').textContent=kind==='variant'?'Une variante décrit une caractéristique réutilisable (monopoutre, électrique, 2 brins…). Les repères, salariés et localisations ont leurs propres champs.':'Utilisez un nom générique pour le type (pont roulant, harnais antichute…). Le repère et la localisation restent distincts.';$('#catalogPeriod').hidden=rename||kind!=='type';$('#catalogItemTitle').textContent=rename?(kind==='type'?'Renommer le type d’équipement':'Renommer la variante'):(kind==='type'?'Créer un type d’équipement':'Créer une variante pour '+type.name);$('#catalogItemForm').elements.label.maxLength=kind==='type'?120:80;$('#catalogItemForm').elements.label.value=rename?item.name:'';$('#catalogItemError').textContent='';$('#catalogItemDialog').showModal();}
$('#addEquipmentType').onclick=()=>openCatalogItem('type','equipment');$('#addEquipmentVariant').onclick=()=>openCatalogItem('variant','equipment');$('#bulkAddType').onclick=()=>openCatalogItem('type','bulk');$('#bulkAddVariant').onclick=()=>openCatalogItem('variant','bulk');
$('#renameEquipmentType').onclick=()=>openCatalogItem('type','equipment',true);$('#renameEquipmentVariant').onclick=()=>openCatalogItem('variant','equipment',true);$('#bulkRenameType').onclick=()=>openCatalogItem('type','bulk',true);$('#bulkRenameVariant').onclick=()=>openCatalogItem('variant','bulk',true);
$('#catalogItemForm').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button:not([type])');if(button.disabled)return;button.disabled=true;try{const c=catalogContext,next=copyData(data),id=c.rename?(c.kind==='type'?c.typeId:c.variantId):uuid(),name=new FormData(event.target).get('label');if(c.kind==='variant'){const issue=technicalVariantIssue(name,next);if(issue)throw Error(issue);}if(c.rename){const count=renameEquipmentLabel(next,c.typeId,c.kind==='variant'?c.variantId:'',name,accountName(),today());if(!confirm(`Renommer ce ${c.kind==='type'?'type':'modèle'} en « ${name.trim()} » ? Le nom de ${count} équipement(s) associé(s) sera mis à jour. Les anciens noms, contrôles, rapports et périodicités seront conservés.`))return;}else if(c.kind==='type'){addEquipmentType(next.equipmentTypes,id,name);next.equipmentTypes.find(t=>t.id===id).months=Number(new FormData(event.target).get('months'));}else addEquipmentVariant(next.equipmentTypes,c.typeId,id,name);if(!valid(next))throw Error('Libellé invalide.');if(!await save(next)){ $('#catalogItemError').textContent=$('#message').textContent;return;}$('#catalogItemDialog').close();const type=c.kind==='type'?id:c.typeId,variant=c.kind==='variant'?id:c.rename?c.variantId:'';if(c.context==='equipment'){if(c.kind==='type'&&!c.rename)$('#equipmentForm').elements.months.value=String(next.equipmentTypes.find(t=>t.id===id).months);namingOptions($('#equipmentType'),type);variantOptions($('#equipmentVariant'),type,variant);updateNamingPreview();}else {namingOptions($('#bulkNamingType'),type);variantOptions($('#bulkNamingVariant'),type,variant);renderNamingGroups();$('#bulkAddVariant').disabled=!type;updateCatalogRenameButtons();}}catch(error){$('#catalogItemError').textContent=error.message;}finally{button.disabled=false;}};

function memoryFlowTrackingHtml(e){const t=e.memoryFlowTracking;if(!t)return '';return `<article class="history memoryflow-comment" data-memoryflow-comment><h3>Commentaire importé de MemoryFlow</h3><small class="report-reference">${t.importedAt?'Ajouté le '+esc(new Date(t.importedAt).toLocaleString('fr-FR',{timeZone:'Europe/Paris'})):'Date de reprise non renseignée'} · ${esc(t.by)}</small><p><b>Dernière date déclarée dans MemoryFlow :</b> <b>${fmt(t.lastDate)}</b> · <b>Échéance reprise :</b> ${fmt(t.nextDate)}<br><b>Résultat et vérificateur :</b> non renseignés dans cet export.<br><b>Source :</b> ${esc(t.fileName)} · ID MemoryFlow ${esc(t.sourceId)}<br><b>Reprise confirmée par :</b> ${esc(t.by)}</p><p>Cette reprise permet le suivi des échéances. Elle ne crée pas une vérification effectuée avec résultat ni un rapport officiel et ne certifie pas la conformité.</p><details><summary>Informations source et reprises précédentes (${e.memoryFlowTrackingHistory?.length||1})</summary>${(e.memoryFlowTrackingHistory||[t]).map(x=>`<p>${fmt(x.lastDate)} · échéance ${fmt(x.nextDate)} · ${esc(x.by)} · ${esc(x.fileName)}</p>`).join('')}${t.sourceRows.map(r=>`<details><summary>Ligne source ${r.line}</summary><dl>${Object.entries(r.fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`).join('')}</details></article>`;}
function namingAuditHtml(e){return `<details class="archive-info"><summary>Noms et classification${e.typeId?' · '+esc(e.standardName):' · à standardiser'}</summary><p><b>Nom actuel :</b> ${esc(e.designation)}<br><b>Nom historique :</b> ${esc(historicalEquipmentName(e))}<br><b>Repère :</b> ${esc(e.equipmentMark)||'Non renseigné'}<br><b>Nom standard :</b> ${esc(e.standardName)||'Non défini'}</p><p class="foot">La classification ne change pas la périodicité, les dates ou les résultats des contrôles.</p>${(e.namingHistory||[]).map(h=>`<p><b>${h.at?esc(new Date(h.at).toLocaleString('fr-FR',{timeZone:'Europe/Paris'})):fmt(h.date)}</b> · ${esc(h.by)}<br>${esc(h.originalName||h.previous.standardName||'Nom libre')} → ${esc(h.newName||h.next.standardName||'Nom libre')}<br>Repère : ${esc(h.next.equipmentMark??h.equipmentMark)||'Non renseigné'}${h.source?'<br>'+esc(h.source):''}</p>`).join('')}</details>`;}

function invalidateNamingPreview(){namingPreview=null;$('#namingPreview').innerHTML='';$('#applyNaming').disabled=true;$('#namingError').textContent='';$('#namingStatus').textContent='';}
function renderNamingGroups(){invalidateNamingPreview();const groups=namingGroups(data.equipment,{search:$('#namingSearch').value,includeNamed:$('#includeNamed').checked}),eligible=new Set(namingGroups(data.equipment,{includeNamed:$('#includeNamed').checked}).flatMap(g=>g.equipment.map(e=>e.id)));namingSelection=new Set([...namingSelection].filter(id=>eligible.has(id)));$('#namingCount').textContent=`${groups.length} noms actuels · ${groups.reduce((n,g)=>n+g.equipment.length,0)} équipements, archives comprises · ${namingSelection.size} sélectionnés`;$('#namingGroups').innerHTML=groups.length?groups.map((g,i)=>`<label class="naming-group"><input type="checkbox" data-naming-group="${i}" ${g.equipment.every(e=>namingSelection.has(e.id))?'checked':''}><span>${esc(g.name)}<small>${g.equipment.length} équipement(s) · ${g.equipment.filter(materialArchived).length} mis au rebut · ${g.equipment.filter(lossArchived).length} introuvable(s)</small></span></label>`).join(''):'<p>Aucun nom à standardiser dans cette sélection.</p>';$('#namingGroups').querySelectorAll('[data-naming-group]').forEach(input=>input.onchange=()=>{const g=groups[Number(input.dataset.namingGroup)];for(const e of g.equipment)if(input.checked)namingSelection.add(e.id);else namingSelection.delete(e.id);invalidateNamingPreview();$('#namingCount').textContent=`${groups.length} noms actuels · ${namingSelection.size} équipements sélectionnés, archives comprises`;});}

function initializeNamingWorkspace(){if(namingInitialized)return;namingInitialized=true;namingOptions($('#bulkNamingType'));variantOptions($('#bulkNamingVariant'),'');$('#bulkAddVariant').disabled=true;renderNamingGroups();updateCatalogRenameButtons();namingReviewUI.refreshRules();selectNamingTab('Proposals',false);}
$('#namingSettings').onclick=()=>namingReviewUI.open();$('#openNamingWorkspace').onclick=()=>namingReviewUI.open();

$('#namingSearch').oninput=renderNamingGroups;$('#includeNamed').onchange=renderNamingGroups;$('#bulkNamingType').onchange=()=>{variantOptions($('#bulkNamingVariant'),$('#bulkNamingType').value);$('#bulkAddVariant').disabled=!$('#bulkNamingType').value;updateCatalogRenameButtons();invalidateNamingPreview();};$('#bulkNamingVariant').onchange=()=>{updateCatalogRenameButtons();invalidateNamingPreview();};
$('#previewNaming').onclick=()=>{try{if(!namingSelection.size)throw Error('Sélectionnez au moins un groupe de noms.');const typeId=$('#bulkNamingType').value,variantId=$('#bulkNamingVariant').value;if(!typeId)throw Error('Choisissez le type cible.');const label=standardizedLabel(data.equipmentTypes,typeId,variantId),items=data.equipment.filter(e=>namingSelection.has(e.id));namingPreview={document:canonical(data),ids:items.map(e=>e.id),typeId,variantId,label};$('#namingPreview').innerHTML=`<h3 id="namingPreviewCount">${items.length} fiche(s) → ${esc(label)}</h3><p>Vérifiez chaque ligne avant confirmation. Les noms d’origine, documents, contrôles et échéances sont conservés.</p><div class="naming-preview"><table><thead><tr><th>Inclure</th><th>Numéro interne / ID</th><th>Nom actuel / secteur</th><th>Nom standard proposé</th></tr></thead><tbody>${items.map(e=>`<tr><td><input type="checkbox" data-naming-include="${esc(e.id)}" checked aria-label="Inclure ${esc(e.identifier)}"></td><td>${esc(e.identifier)} · ID ${e.siteId}${e.archived?(lossArchived(e)?' · Introuvable':' · Mis au rebut'):''}</td><td>${esc(e.designation)}<br>${esc(sectorLabel(e.sector)||'Secteur non renseigné')} ${esc(e.zone||'')}${e.standardName?'<br>Actuellement : '+esc(e.standardName):''}</td><td>${esc(label)}</td></tr>`).join('')}</tbody></table></div>`;$('#namingPreview').querySelectorAll('[data-naming-include]').forEach(input=>input.onchange=()=>{if(input.checked)namingSelection.add(input.dataset.namingInclude);else namingSelection.delete(input.dataset.namingInclude);namingPreview.ids=items.filter(e=>namingSelection.has(e.id)).map(e=>e.id);$('#namingPreviewCount').textContent=namingPreview.ids.length+' fiche(s) → '+label;$('#applyNaming').disabled=namingPreview.ids.length===0;$('#namingCount').textContent=namingPreview.ids.length+' équipement(s) sélectionné(s) après vérification';});$('#namingError').textContent='';$('#applyNaming').disabled=false;}catch(error){$('#namingError').textContent=error.message;}};
$('#applyNaming').onclick=async()=>{const button=$('#applyNaming');if(button.disabled)return;button.disabled=true;try{const p=namingPreview;if(!p||p.document!==canonical(data))throw Error('Les données ont changé : refaites la prévisualisation.');if(!confirm(`Associer ${p.ids.length} équipement(s) à « ${p.label} » ? Vérifiez qu’ils correspondent tous à ce type et cette variante. Le nom actuel sera remplacé par le nom standard ; le nom d’origine restera conservé dans l’historique.`)){button.disabled=false;return;}const next=copyData(data);for(const e of next.equipment.filter(e=>p.ids.includes(e.id)))applyEquipmentNaming(e,next.equipmentTypes,p.typeId,p.variantId,accountName(),today(),{context:next});if(!valid(next))throw Error('Classification invalide.');if(!await save(next))throw Error($('#message').textContent);namingSelection.clear();renderNamingGroups();$('#namingStatus').textContent=`${p.ids.length} fiche(s) standardisée(s). Les noms d’origine et historiques sont conservés.`;}catch(error){$('#namingError').textContent=error.message;button.disabled=false;}};
function initializeImportTools(){$('#dataMode').textContent=cloud?`Supabase · révision ${cloud.revision}. Les données locales ne sont pas modifiées.`:'Mode local : les données restent dans ce navigateur. Supabase est désactivé.';$('#validateMigration').disabled=!pendingMigration;$('#trackingReview').textContent=trackingReviewText();$('#migrateLocal').disabled=!cloud||cloud.revision!==0;$('#migrationFile').disabled=!cloud||cloud.revision!==0;}
$('#dataSettings').onclick=()=>setView('administration');
function migrationSummary(document){return `${document.equipment.length} équipements, ${document.equipment.reduce((n,e)=>n+e.controls.length,0)} contrôles. Propriétaires, dates, archives et justificatifs seront conservés.`;}
async function migrateDocument(document,source){
 if(!cloud)throw Error('Activez Supabase après sa configuration.');
 if(!valid(document))throw Error('Sauvegarde invalide. Aucune importation effectuée.');
 const upgraded=upgrade(copyData(document));
 if(!confirm(migrationSummary(upgraded)+' Importer dans l’espace cloud vierge ? Conservez votre export JSON.'))return;
 const result=await cloud.migrate(upgraded,source);pendingMigration={receipt:result.receipt,document:upgraded};data=result.payload;render();$('#validateMigration').disabled=false;$('#migrateLocal').disabled=true;$('#migrationFile').disabled=true;$('#dataStatus').textContent='Importation et relecture intégrale réussies. Vérifiez les fiches et les rapports, puis cliquez sur « Valider la migration ». La sauvegarde locale est conservée.';
}
$('#migrateLocal').onclick=async()=>{try{const raw=localStorage.getItem(KEY);if(!raw)throw Error('Aucune sauvegarde locale sur cette adresse. Importez le fichier JSON exporté depuis l’ancien site.');await migrateDocument(JSON.parse(raw),'Stockage local '+KEY)}catch(error){$('#dataStatus').textContent=error.message}};
$('#migrationFile').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Maximum 20 Mo.');await migrateDocument(JSON.parse(await file.text()),file.name)}catch(error){$('#dataStatus').textContent=error.message}finally{event.target.value=''}};
$('#validateMigration').onclick=async()=>{try{if(!pendingMigration)throw Error('Pas de migration en attente dans cette session.');if(!confirm('Avez-vous vérifié les équipements, les dates, les propriétaires, les historiques et les PDF ?'))return;await cloud.validate(pendingMigration.receipt,pendingMigration.document);$('#dataStatus').textContent='Migration validée et tracée dans Supabase. Vos données locales restent conservées.';$('#validateMigration').disabled=true}catch(error){$('#dataStatus').textContent=error.message}};
let trackingPreview=null;
function updateTrackingApply(){const items=trackingPreview?.items||[];$('#trackingApply').disabled=!$('#trackingConfirmed').checked||!items.some(i=>i.status==='ready')||(items.some(i=>i.status==='error')&&!$('#trackingPartial').checked);}
$('#trackingConfirmed').onchange=updateTrackingApply;$('#trackingPartial').onchange=updateTrackingApply;
$('#trackingFile').onchange=async event=>{trackingPreview=null;$('#trackingApply').disabled=true;$('#trackingConfirmed').checked=false;$('#trackingPartial').checked=false;$('#trackingPreview').innerHTML='';$('#trackingSqlHelp').hidden=true;try{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Fichier limité à 5 Mo.');$('#trackingStatus').textContent='Analyse des identifiants et des dernières dates…';const rows=file.name.toLowerCase().endsWith('.csv')?parseTrackingCsv(await file.text()):await globalThis.VGPReadExcel(file);const report=analyzeTrackingRows(rows,data,today());trackingPreview={...report,document:canonical(data),revision:cloud?.revision,fileName:file.name};const items=report.items;$('#trackingPreview').innerHTML=`<p>Fichier analysé : <b>${esc(file.name)}</b></p><p>${report.sourceLines} lignes source · ${report.ignored} lignes d’autres niveaux ignorées · ${items.length} équipements réglementaires.<br>${items.filter(i=>i.status==='ready').length} associations possibles · ${items.filter(i=>i.status==='duplicate').length} reprises déjà présentes · ${items.filter(i=>i.status==='error').length} erreurs à corriger.</p><p>Les dates déclarées seront conservées séparément des contrôles réalisés avec résultat et vérificateur. Aucun équipement ni rapport officiel n’est créé.</p><div style="max-height:350px;overflow:auto"><table><thead><tr><th>ID MemoryFlow / numéro</th><th>Fiche du site</th><th>Dernière date source</th><th>Échéance source</th><th>Analyse</th></tr></thead><tbody>${items.map(i=>{const e=data.equipment.find(e=>e.id===i.equipmentId);return `<tr><td>${esc(i.sourceId)} · ${esc(i.identifier)}</td><td>${e?esc(equipmentName(e))+' · ID '+e.siteId:'Non associée'}</td><td>${fmt(i.lastDate)}</td><td>${fmt(i.nextDate)}${i.months?' · '+i.months+' mois':''}${i.previousDate?'<br>Ancienne date manuelle : '+fmt(i.previousDate):''}</td><td>${esc(i.message||'Association par '+i.match)}</td></tr>`}).join('')}</tbody></table></div>`;$('#trackingStatus').textContent='Analyse terminée : vérifiez les associations, puis confirmez les dates et règles source.';updateTrackingApply();}catch(error){$('#trackingStatus').textContent=error.message;}finally{event.target.value='';}};
$('#trackingApply').onclick=async()=>{const button=$('#trackingApply');if(button.disabled)return;button.disabled=true;try{const p=trackingPreview;if(!p||p.document!==canonical(data)||p.revision!==cloud?.revision)throw Error('Les données ont changé : analyser de nouveau le fichier.');if(!$('#trackingConfirmed').checked)throw Error('Confirmez les échéances et périodicités après vérification.');if(p.items.some(i=>i.status==='error')&&!$('#trackingPartial').checked)throw Error('Corrigez les erreurs ou choisissez l’association partielle.');const n=p.items.filter(i=>i.status==='ready').length;if(!confirm(`Associer les dernières dates déclarées à ${n} fiche(s) existante(s) et reprendre leurs échéances et périodicités ? Aucun contrôle avec résultat ne sera inventé. Les erreurs et reprises déjà présentes seront ignorées.`)){updateTrackingApply();return;}const next=applyTrackingImport(data,p.items,{today:today(),author:accountName(),fileName:p.fileName});if(!valid(next))throw Error('Format de reprise invalide : aucune donnée modifiée.');$('#trackingStatus').textContent='Enregistrement des '+n+' associations dans Supabase… Patientez jusqu’à la confirmation.';button.textContent='Enregistrement en cours…';if(!await save(next))throw Error($('#message').textContent);trackingPreview=null;$('#trackingStatus').textContent=`${n} fiche(s) associée(s). Les échéances alimentent le suivi à faire / en retard ; les dates historiques restent identifiées comme déclarées dans MemoryFlow. Aucun contrôle avec résultat créé.`;}catch(error){$('#trackingStatus').textContent=error.message;$('#trackingSqlHelp').hidden=!error.message.includes('004_fast_writes.sql');updateTrackingApply();}finally{button.textContent='Associer les dernières dates aux fiches';}};
function updateExcelApply(){const items=excelPreview?.items||[];$('#excelApply').disabled=!items.some(i=>i.status==='ready')||(items.some(i=>i.status==='error')&&!$('#excelPartial').checked);}
$('#excelPartial').onchange=updateExcelApply;
$('#excelFile').onchange=async event=>{excelPreview=null;$('#excelPartial').checked=false;$('#excelApply').disabled=true;$('#excelPreview').innerHTML='';$('#dataStatus').textContent='';try{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Fichier Excel limité à 5 Mo.');$('#dataStatus').textContent='Lecture et analyse du fichier…';const rows=await globalThis.VGPReadExcel(file);excelPreview={revision:cloud?.revision,document:canonical(data),fileName:file.name,items:analyzeRows(rows,data,today())};const items=excelPreview.items,grouped=items.some(i=>i.sourceLines);$('#excelPreview').innerHTML=`<p>${rows.length-1} lignes source${grouped?' regroupées en '+items.length+' fiches équipement':''}. ${items.filter(i=>i.status==='ready').length} ajouts possibles · ${items.filter(i=>i.status==='duplicate').length} doublons ignorés · ${items.filter(i=>i.status==='error').length} erreurs à corriger.</p>${grouped?'<p class="foot">Export MemoryFlow reconnu : les niveaux de suivi sont regroupés par ID source. Les dates restent à valider. Aucun contrôle réalisé sans résultat et vérificateur.</p>':''}<div style="overflow-x:auto"><table><thead><tr><th>Ligne / ID source</th><th>Équipement</th><th>Nomenclature</th><th>Analyse</th><th>Informations à vérifier</th></tr></thead><tbody>${items.map(i=>`<tr><td>${i.line}${i.externalId?' · ID source '+esc(i.externalId)+' · '+i.sourceLines+' ligne(s)':''}</td><td>${esc(i.row.identifier)} · ${esc(i.row.designation)}</td><td>${i.naming?.typeId?esc(standardizedLabel(data.equipmentTypes,i.naming.typeId,i.naming.variantId)):'Non reconnue'}${i.naming?'<small>'+esc(i.naming.confidence==='rule'?'Règle exacte validée : applicable après confirmation':'Proposition à revoir dans Standardisation automatique')+'</small>':''}${i.naming?.equipmentMark?'<small>Repère : '+esc(i.naming.equipmentMark)+'</small>':''}</td><td>${esc(i.message||'Prêt à créer')}${i.row.nextDate?'<br>Échéance source à valider : '+fmt(i.row.nextDate):''}${i.row.lastDate?'<br>Dernière date source : '+fmt(i.row.lastDate):''}</td><td>${(i.warnings||[]).map(esc).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`;const ruleCount=items.filter(i=>i.status==='ready'&&i.naming?.confidence==='rule').length;if(ruleCount)$('#excelPreview').insertAdjacentHTML('beforeend',`<label class="approval-check"><input id="excelNamingRules" type="checkbox" checked>Appliquer les règles de nomenclature déjà validées à ${ruleCount} nouvelle(s) fiche(s), sans modifier les périodicités ou les échéances.</label>`);$('#dataStatus').textContent='Analyse terminée. Vérifiez l’aperçu avant de confirmer.';updateExcelApply();}catch(error){$('#dataStatus').textContent=error.message}finally{event.target.value=''}};
$('#excelApply').onclick=async()=>{try{if(!excelPreview||excelPreview.document!==canonical(data)||excelPreview.revision!==cloud?.revision)throw Error('Les données ont changé. Analysez de nouveau le fichier.');const errors=excelPreview.items.filter(i=>i.status==='error').length;if(errors&&!$('#excelPartial').checked)throw Error('Corrigez les erreurs ou choisissez explicitement l’import partiel.');const ready=excelPreview.items.filter(i=>i.status==='ready');if(!ready.length)throw Error('Aucun équipement à ajouter.');if(!confirm(`Créer ${ready.length} équipement(s) ? ${errors} fiche(s) en erreur et ${excelPreview.items.filter(i=>i.status==='duplicate').length} doublon(s) seront ignorés. Les fiches existantes restent inchangées. Les échéances importées restent à valider.${$('#excelNamingRules')?.checked?' Les règles exactes de nomenclature présentées dans l’aperçu seront appliquées.':''}`))return;const next=copyData(data);for(const item of ready){const row=item.row,id=uuid(),date=today(),first=null;const e={id,siteId:next.nextVgpId++,identifier:row.identifier,equipmentMark:row.equipmentMark||'',designation:row.designation,serialNumber:row.serialNumber||'',location:row.location||'',category:'',assignment:'',sector:row.sector||'',zone:row.zone||'',team:row.team||'',owner:next.owners.find(o=>normalize(o)===normalize(row.owner))||row.owner||'',months:row.months,createdDate:date,comments:row.comments||`Fiche importée le ${fmt(date)}`,family:row.family||'',...(row.sourceImport?{sourceImport:{...row.sourceImport,fileName:excelPreview.fileName,importedAt:new Date().toISOString(),importedBy:accountName()},dateValidation:{validated:false},periodicityValidation:{validated:false,months:row.months,reason:'Fréquence reprise de l’export, à valider par l’entreprise',by:accountName()}}:{}),firstControlDate:first,manualNextControlDate:row.nextDate,manualControlId:null,scheduledControl:null,archived:false,archiveHistory:[],pendingArchive:null,controls:[]};if($('#excelNamingRules')?.checked)applyImportedNamingRule(e,next,{confirmed:true,by:accountName(),at:new Date().toISOString()});if(row.lastDate&&!row.sourceImport){const cid=uuid();e.controls.push({id:cid,reportId:nextReportNumber(next),date:row.lastDate,intervenant:row.verifier,result:row.result,observations:'Import Excel : justificatif à joindre séparément.',created:Date.now(),enteredBy:accountName(),enteredById:cloud?.session?.user?.id||null,attachment:null,equipmentSnapshot:equipmentSnapshot(e)});e.manualControlId=cid;}if(row.owner&&!next.owners.some(o=>normalize(o)===normalize(row.owner)))next.owners.push(row.owner);if(row.email){const contact=next.ownerContacts.find(c=>normalize(c.owner)===normalize(row.owner));if(!contact)next.ownerContacts.push({owner:row.owner,email:row.email});else if(!contact.email)contact.email=row.email;}next.equipment.push(e);}if(!valid(next))throw Error('Import invalide. Corrigez le fichier.');if(await save(next)){$('#dataStatus').textContent='Équipements ajoutés. Les doublons ont été ignorés, aucune fiche existante remplacée.';excelPreview=null;$('#excelApply').disabled=true}else $('#dataStatus').textContent=$('#message').textContent}catch(error){$('#dataStatus').textContent=error.message}};


function nextReportNumber(state){return String(Math.max(0,...state.equipment.flatMap(e=>[...e.controls,...(e.archiveHistory||[])].map(c=>/^\d+$/.test(c.reportId||'')?Number(c.reportId):0)))+1);}
$('#ownerPicker').onchange=()=>{if($('#ownerPicker').value)openOwner($('#ownerPicker').value);};$('#ownerSearch').oninput=renderOwners;$('#ownerSort').onchange=renderOwners;
$('#createAssociatedEquipment').onclick=()=>{const owner=selectedOwner;$('#associateDialog').close();edit();ownerOptions(owner);};
